def _print_uncalled_function_warnings(nb, up2id=None):
    warnings = _uncalled_function_warnings(nb, up2id=up2id)
    if not warnings: return []
    print("Execution warnings:")
    for warning in warnings: print(f"- {warning}")
    return warnings

